-- Source: CMaNGOS Classic DB e4825cf48176edff313d78de66b0beb14371c8eb,
-- Full_DB/ClassicDB_1_12_1_z2815.sql.gz; GPL-2.0-or-later. Source GUIDs
-- are retained in the temporary manifest for audit. Existing Zero spawns are
-- matched by entry, map and position; new GUIDs occupy 800000 onward.
-- Apply only after Rel22_06_005 and with the matching core/controller.
-- MyISAM world tables do not roll back; preflight rejects collisions before
-- permanent writes, and the INSERTs can be rerun after interruption.
DROP PROCEDURE IF EXISTS `update_mangos`;

DELIMITER $$

CREATE DEFINER=`root`@`localhost` PROCEDURE `update_mangos`()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SHOW ERRORS;
        SELECT '* UPDATE FAILED *' AS `===== Status =====`,
               @cCurResult AS `===== DB is on Version: =====`;
        RESIGNAL;
    END;

    SET @cCurVersion := (SELECT `version` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurStructure := (SELECT `structure` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurContent := (SELECT `content` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);

    SET @cOldVersion = '22';
    SET @cOldStructure = '06';
    SET @cOldContent = '005';

    SET @cNewVersion = '22';
    SET @cNewStructure = '06';
    SET @cNewContent = '006';
    SET @cNewDescription = 'AQ_War_Effort_Spawns';
    SET @cNewComment = 'Add AQ war effort and ten hour war spawns';

    SET @cCurResult := (SELECT `description` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cOldResult := (SELECT `description` FROM `db_version` WHERE `version` = @cOldVersion AND `structure` = @cOldStructure AND `content` = @cOldContent);
    SET @cNewResult := (SELECT `description` FROM `db_version` WHERE `version` = @cNewVersion AND `structure` = @cNewStructure AND `content` = @cNewContent);

    IF (@cCurResult = @cOldResult) THEN
        START TRANSACTION;

        CREATE TEMPORARY TABLE IF NOT EXISTS `aq_creature_stage` (
          `source_guid` INT UNSIGNED PRIMARY KEY, `guid` INT UNSIGNED NOT NULL,
          `entry` MEDIUMINT UNSIGNED NOT NULL, `map` INT UNSIGNED NOT NULL,
          `x` FLOAT NOT NULL, `y` FLOAT NOT NULL, `z` FLOAT NOT NULL,
          `orientation` FLOAT NOT NULL, `respawn` INT UNSIGNED NOT NULL,
          `wander` FLOAT NOT NULL, `movement` TINYINT UNSIGNED NOT NULL,
          `event` SMALLINT NOT NULL, `new_spawn` BOOLEAN NOT NULL
        ) ENGINE=InnoDB;
        DELETE FROM `aq_creature_stage`;
        CREATE TEMPORARY TABLE IF NOT EXISTS `aq_object_stage` (
          `source_guid` INT UNSIGNED PRIMARY KEY, `guid` INT UNSIGNED NOT NULL,
          `entry` MEDIUMINT UNSIGNED NOT NULL, `map` INT UNSIGNED NOT NULL,
          `x` FLOAT NOT NULL, `y` FLOAT NOT NULL, `z` FLOAT NOT NULL,
          `orientation` FLOAT NOT NULL, `r0` FLOAT NOT NULL, `r1` FLOAT NOT NULL,
          `r2` FLOAT NOT NULL, `r3` FLOAT NOT NULL, `respawn` INT NOT NULL,
          `event` SMALLINT NOT NULL, `new_spawn` BOOLEAN NOT NULL
        ) ENGINE=InnoDB;
        DELETE FROM `aq_object_stage`;
        CREATE TEMPORARY TABLE IF NOT EXISTS `aq_path_stage` (
          `entry` MEDIUMINT UNSIGNED NOT NULL, `point` MEDIUMINT UNSIGNED NOT NULL,
          `x` FLOAT NOT NULL, `y` FLOAT NOT NULL, `z` FLOAT NOT NULL,
          `orientation` FLOAT NOT NULL, `waittime` INT UNSIGNED NOT NULL,
          `script` MEDIUMINT UNSIGNED NOT NULL, PRIMARY KEY (`entry`,`point`)
        ) ENGINE=InnoDB;
        DELETE FROM `aq_path_stage`;

        -- Reject GUID reuse, moved existing spawns, incompatible event links,
        -- missing templates and custom routes before touching permanent data.
        IF EXISTS (SELECT 1 FROM `aq_creature_stage` s LEFT JOIN `creature` c ON c.guid=s.guid
                   WHERE (s.new_spawn=0 AND c.guid IS NULL) OR
                     (c.guid IS NOT NULL AND (c.id<>s.entry OR c.map<>s.map OR
                      POW(c.position_x-s.x,2)+POW(c.position_y-s.y,2)+POW(c.position_z-s.z,2)>=4))) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ creature spawn conflict';
        END IF;
        IF EXISTS (SELECT 1 FROM `aq_creature_stage` s LEFT JOIN `creature_template` t ON t.entry=s.entry WHERE t.entry IS NULL) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ creature template missing';
        END IF;
        IF EXISTS (SELECT 1 FROM `aq_creature_stage` s JOIN `game_event_creature` e ON e.guid=s.guid WHERE e.event<>s.event) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ creature event conflict';
        END IF;
        IF EXISTS (SELECT 1 FROM `aq_object_stage` s LEFT JOIN `gameobject` g ON g.guid=s.guid
                   WHERE (s.new_spawn=0 AND g.guid IS NULL) OR
                     (g.guid IS NOT NULL AND (g.id<>s.entry OR g.map<>s.map OR
                      POW(g.position_x-s.x,2)+POW(g.position_y-s.y,2)+POW(g.position_z-s.z,2)>=4))) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ gameobject spawn conflict';
        END IF;
        IF EXISTS (SELECT 1 FROM `aq_object_stage` s LEFT JOIN `gameobject_template` t ON t.entry=s.entry WHERE t.entry IS NULL) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ gameobject template missing';
        END IF;
        IF EXISTS (SELECT 1 FROM `aq_object_stage` s JOIN `game_event_gameobject` e ON e.guid=s.guid WHERE e.event<>s.event) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ gameobject event conflict';
        END IF;
        IF EXISTS (SELECT 1 FROM `creature_movement_template` p LEFT JOIN `aq_path_stage` s ON s.entry=p.entry AND s.point=p.point
                   WHERE p.entry IN (15740,15741,15742) AND
                     (s.entry IS NULL OR POW(p.position_x-s.x,2)+POW(p.position_y-s.y,2)+POW(p.position_z-s.z,2)>0.01 OR p.script_id<>s.script)) OR
           EXISTS (SELECT 1 FROM `db_scripts` WHERE script_type=3 AND id IN (1574001,1574101,1574201)
                   AND (command<>20 OR datalong<>1 OR (id=1574101 AND datalong2<>50) OR (id<>1574101 AND datalong2<>25))) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ colossus path or script conflict';
        END IF;

          `position_x`,`position_y`,`position_z`,`orientation`,`spawntimesecs`,
          `spawndist`,`currentwaypoint`,`curhealth`,`curmana`,`DeathState`,`MovementType`)
        SELECT s.guid,s.entry,s.map,0,0,s.x,s.y,s.z,s.orientation,s.respawn,
          s.wander,0,GREATEST(t.MinLevelHealth,1),t.MinLevelMana,0,s.movement
          FROM `aq_creature_stage` s JOIN `creature_template` t ON t.entry=s.entry WHERE s.new_spawn=1;
          SELECT guid,event FROM `aq_creature_stage`;
          `orientation`,`rotation0`,`rotation1`,`rotation2`,`rotation3`,`spawntimesecs`,`animprogress`,`state`)
        SELECT guid,entry,map,x,y,z,orientation,r0,r1,r2,r3,respawn,100,1
          FROM `aq_object_stage` WHERE new_spawn=1;
          SELECT guid,event FROM `aq_object_stage`;
          SELECT entry,point,x,y,z,orientation,waittime,script FROM `aq_path_stage`;
          SELECT 3,t.id,0,20,1,t.distance,'AQ war effort colossus wandering'
          FROM (SELECT 1574001 AS id,25 AS distance UNION ALL SELECT 1574101,50 UNION ALL SELECT 1574201,25) t
          WHERE NOT EXISTS (SELECT 1 FROM `db_scripts` d WHERE d.script_type=3 AND d.id=t.id);

            @cNewContent, @cNewDescription, @cNewComment);
        SET @cNewResult := (SELECT `description` FROM `db_version`
            WHERE `version` = @cNewVersion AND `structure` = @cNewStructure
              AND `content` = @cNewContent);
        COMMIT;
        SELECT '* UPDATE COMPLETE *' AS `===== Status =====`,
               @cNewResult AS `===== DB is now on Version =====`;
    ELSE
        IF (@cCurResult = @cNewResult) THEN
            SELECT '* UPDATE SKIPPED *' AS `===== Status =====`,
                   @cCurResult AS `===== DB is already on Version =====`;
        ELSE
            IF (@cCurResult IS NULL) THEN
                SELECT '* UPDATE FAILED *' AS `===== Status =====`,
                       'Unable to locate DB Version Information' AS `============= Error Message =============`;
            ELSE
                SET @cCurOutput = CONCAT(@cCurVersion, '_', @cCurStructure,
                    '_', @cCurContent, ' - ', @cCurResult);
                SET @cOldOutput = CONCAT(@cOldVersion, '_', @cOldStructure,
                    '_', @cOldContent, ' - ',
                    COALESCE(@cOldResult, 'IS NOT APPLIED'));
                SELECT '* UPDATE SKIPPED *' AS `===== Status =====`,
                       @cOldOutput AS `=== Expected ===`,
                       @cCurOutput AS `===== Found Version =====`;
            END IF;
        END IF;
    END IF;
END $$

DELIMITER ;

CALL update_mangos();

DROP PROCEDURE IF EXISTS `update_mangos`;
